#include <vector>
#include <numeric>
#include <cstdlib>

class Solution {
public:
    int countValidSelections(std::vector<int>& nums) {
        long long total = 0;
        for (int x : nums) total += x;
        long long left_sum = 0;
        int ans = 0;

        for (int x : nums) {
            if (x == 0) {
                long long right_sum = total - left_sum;
                long long diff = std::abs(left_sum - right_sum);
                if (diff == 0) ans += 2;
                else if (diff == 1) ans += 1;
            } else {
                left_sum += x;
            }
        }
        return ans;
    }
};

class Solution {
    public int countValidSelections(int[] nums) {
        long total = 0;
        for (int x : nums) total += x;
        long leftSum = 0;
        int ans = 0;

        for (int x : nums) {
            if (x == 0) {
                long rightSum = total - leftSum;
                long diff = Math.abs(leftSum - rightSum);
                if (diff == 0) ans += 2;
                else if (diff == 1) ans += 1;
            } else {
                leftSum += x;
            }
        }
        return ans;
    }
}

var countValidSelections = function(nums) {
    let total = 0;
    for (const x of nums) total += x;
    let leftSum = 0;
    let ans = 0;

    for (const x of nums) {
        if (x === 0) {
            const rightSum = total - leftSum;
            const diff = Math.abs(leftSum - rightSum);
            if (diff === 0) ans += 2;
            else if (diff === 1) ans += 1;
        } else {
            leftSum += x;
        }
    }
    return ans;
};
